# 별자리
con="양자리:3월 21일~4월 19일 황소자리:4월 20일~5월 20일 쌍둥이자리:5월 21일~6월 21일 게자리:6월 22일~7월 22일 사자자리:7월 23일~8월 22일 처녀자리:8월 23일~9월 23일 천칭자리:9월 24일~10월 23일 전갈자리:10월 24일~11월 22일 사수자리:11월 23일~12월 21일 염소자리:12월 22일~1월 19일 물병자리:1월 20일~2월 18일 물고기자리:2월 19일~3월 20일".split(" ")
# 위 split은 공백이 섞여서 직접 만든다
cons=[("양자리","3/21~4/19","🐏"),("황소자리","4/20~5/20","🐂"),("쌍둥이자리","5/21~6/21","👯"),("게자리","6/22~7/22","🦀"),("사자자리","7/23~8/22","🦁"),("처녀자리","8/23~9/23","👧"),("천칭자리","9/24~10/23","⚖️"),("전갈자리","10/24~11/22","🦂"),("사수자리","11/23~12/21","🏹"),("염소자리","12/22~1/19","🐐"),("물병자리","1/20~2/18","🏺"),("물고기자리","2/19~3/20","🐟")]
rows=[]
for n,d,e in cons:
    rows.append([f"{e} 이 별자리의 이름은?",n,[]])
    rows.append([f"{n}의 기간은?",d,[x[1] for x in cons if x[0]!=n][:3]])
import random
random.seed(7)
rows=[[q,a,(w if w else [x[0] for x in random.sample([c for c in cons if c[0]!=a],3)])] for q,a,w in rows]
rows=[[q,a,w] for q,a,w in rows]
# 기간 문제는 보기를 무작위로 다르게
for r in rows:
    if "의 기간은?" in r[0]:
        n=r[0].split("의")[0]; r[2]=[x[1] for x in random.sample([c for c in cons if c[0]!=n],3)]
make(H+"zodiac-quiz.html","별자리 퀴즈","♈",260,"zodiac-quiz-best-v1","열두 별자리의 이름과 기간을 맞혀 보세요.",rows,label="별자리 퀴즈")
